public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    int n = nums.length;
    if (n == 0) {
        return res;
    }
    int[] perm = new int[n];
    boolean[] used = new boolean[n];
    int[] stack = new int[n];
    int depth = 0;
    while (depth >= 0) {
        if (depth == n) {
            List<Integer> list = new ArrayList<>(n);
            for (int val : perm) {
                list.add(val);
            }
            res.add(list);
            depth--;
            if (depth >= 0) {
                int idx = stack[depth];
                used[idx] = false;
                stack[depth] = -1;
            }
        } else {
            boolean found = false;
            for (int i = 0; i < n; i++) {
                if (!used[i]) {
                    perm[depth] = nums[i];
                    used[i] = true;
                    stack[depth] = i;
                    depth++;
                    found = true;
                    break;
                }
            }
            if (!found) {
                depth--;
                if (depth >= 0) {
                    int idx = stack[depth];
                    used[idx] = false;
                    stack[depth] = -1;
                }
            }
        }
    }
    return res;
}

private void backtrack(int[] nums, boolean[] used, java.util.List<Integer> current, java.util.List<java.util.List<Integer>> result) {
    if (current.size() == nums.length) {
        result.add(new java.util.ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        current.add(nums[i]);
        backtrack(nums, used, current, result);
        current.remove(current.size() - 1);
        used[i] = false;
    }
}

