    }
    if (minLen == 0) {
        return 0;
    }
    String first = strings.get(0);
    // Search lengths from longest possible down to 1
    for (int len = minLen; len >= 1; len--) {
        // Generate all unique substrings of this length from the first string
        Set<String> candidates = new HashSet<>();
        for (int i = 0; i <= first.length() - len; i++) {
            String sub = first.substring(i, i + len);
            candidates.add(sub);
            // Also consider the reverse of the substring as a candidate
            candidates.add(new StringBuilder(sub).reverse().toString());
        }
        // Check each candidate against all strings
        for (String candidate : candidates) {
            String revCandidate = new StringBuilder(candidate).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (s == null) {
                    ok = false;
                    break;
                }
                if (!(s.contains(candidate) || s.contains(revCandidate))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

