public static int countDoubles(int[] numbers) {
    // Build a frequency map of the numbers
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int n : numbers) {
        freq.put(n, freq.getOrDefault(n, 0) + 1);
    }
    int count = 0;
    for (int n : numbers) {
        // Only even numbers can be double of an integer
        if (n % 2 == 0) {
            int half = n / 2;
            Integer halfFreq = freq.get(half);
            if (halfFreq != null) {
                if (half == n) {
                    // same number: need at least two occurrences
                    if (halfFreq >= 2) {
                        count++;
                    }
                } else {
                    count++;
                }
            }
        }
    }
    return count;
}

