        String src = sbSrc.toString();
        StringBuilder sbDst = new StringBuilder();
        for (int j = 0; j < n; j++) {
            if (j > 0) sbDst.append(',');
            sbDst.append(p[n + j]);
        }
        String dst = sbDst.toString();
        adj.computeIfAbsent(src, k -> new java.util.ArrayList<>()).add(dst);
        adj.computeIfAbsent(dst, k -> new java.util.ArrayList<>()).add(src);
    }
    StringBuilder sbStart = new StringBuilder();
    for (int i = 0; i < n; i++) {
        if (i > 0) sbStart.append(',');
