public static String appx(String word1, String word2) {
    int commonCount = 0;
    String w1 = word1 != null ? word1 : "";
    String w2 = word2 != null ? word2 : "";
    for (int i = 0; i < w1.length(); i++) {
        if (w2.indexOf(w1.charAt(i)) != -1) {
            commonCount++;
        }
    }
    for (int i = 0; i < w2.length(); i++) {
        if (w1.indexOf(w2.charAt(i)) != -1) {
            commonCount++;
        }
    }
    int denom = w1.length() + w2.length();
    String prefix = "appx(" + word1 + ", " + word2 + ") = ";
    if (commonCount == 0) {
        return prefix + "0";
    }
    // Reduce the fraction
    int a = commonCount;
    int b = denom;
    int temp;
    while (b != 0) {
        temp = a % b;
        a = b;
        b = temp;
    }
    int gcd = a;
    int num = commonCount / gcd;
    int den = denom / gcd;
    if (num == 1 && den == 1) {
        return prefix + "1";
    }
    return prefix + num + "/" + den;
}

public static String appx(String word1, String word2) {
    java.util.Set<Character> set1 = new java.util.HashSet<>();
    for (char c : word1.toCharArray()) {
        set1.add(c);
    }

    java.util.Set<Character> set2 = new java.util.HashSet<>();
    for (char c : word2.toCharArray()) {
        set2.add(c);
    }

    java.util.Set<Character> intersection = new java.util.HashSet<>(set1);
    intersection.retainAll(set2);
    int common = intersection.size() * 2; // Common letters counted twice

    int lenSum = word1.length() + word2.length();
    String result;
    if (common == 0) {
        result = "0";
    } else if (common == lenSum) {
        result = "1";
    } else {
        int gcd = gcd(common, lenSum);
        int num = common / gcd;
        int den = lenSum / gcd;
        result = num + "/" + den;
    }

    return "appx(" + word1 + ", " + word2 + ") = " + result;
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

public static String convertDatesToWeekdays(String date) {
    // Parse the input date string using the format "MM dd yyyy"
    java.time.format.DateTimeFormatter inputFormatter =
            java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy");
    java.time.LocalDate localDate;
    try {
        localDate = java.time.LocalDate.parse(date, inputFormatter);
    } catch (java.time.format.DateTimeParseException e) {
        return "Invalid date format";
    }

    // Retrieve month name, day, year, and weekday
    String monthName = localDate.getMonth()
                                .getDisplayName(java.time.format.TextStyle.FULL,
                                                 java.util.Locale.ENGLISH);
    int day = localDate.getDayOfMonth();
    int year = localDate.getYear();
    String weekday = localDate.getDayOfWeek()
                              .getDisplayName(java.time.format.TextStyle.FULL,
                                               java.util.Locale.ENGLISH);

    // Construct the result string
    return monthName + " " + day + ", " + year + " is a " + weekday;
