public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length == 0 || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 == 1) {
        return false; // cannot pair all elements
    }

    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k; // handle negative numbers
        freq[rem]++;
    }

    // remainder 0 must have even count
    if (freq[0] % 2 != 0) {
        return false;
    }

    // if k is even, remainder k/2 must also have even count
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) {
        return false;
    }

    // For all other remainders, freq[r] must equal freq[k - r]
    for (int r = 1; r <= k / 2; r++) {
