    for (int num : arr) {
        int r = ((num % k) + k) % k;  // ensure non‑negative remainder
        count[r]++;
    }
    // remainder 0 must be paired within itself
    if (count[0] % 2 != 0) {
        return false;
    }
    // if k is even, remainder k/2 must also be paired within itself
    if (k % 2 == 0) {
        if (count[k / 2] % 2 != 0) {
            return false;
        }
    }
    int limit = k / 2;
    if (k % 2 == 0) {
        limit--; // exclude the middle remainder already checked
    }
    for (int r = 1; r <= limit; r++) {
        if (count[r] != count[k - r]) {
            return false;
        }
    }
    return true;
}

