public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build adjacency list
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        int u = e[0], v = e[1];
        adj[u].add(v);
        adj[v].add(u);
    }

    // Prepare parent array and traversal order (pre-order)
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -1);
    parent[0] = -2; // root has no parent
    java.util.Deque<int[]> stack = new java.util.ArrayDeque<>();
    stack.push(new int[]{0, -1});
    java.util.List<Integer> order = new java.util.ArrayList<>();

    while (!stack.isEmpty()) {
        int[] cur = stack.pop();
        int node = cur[0], par = cur[1];
        parent[node] = par;
        order.add(node);
        for (int nb : adj[node]) {
            if (nb != par) {
                stack.push(new int[]{nb, node});
            }
        }
    }

    int time = 0;
    boolean[] needed = new boolean[n];

    // Process nodes in post-order (reverse of traversal order)
    for (int i = order.size() - 1; i >= 0; i--) {
        int node = order.get(i);
        for (int nb : adj[node]) {
            if (parent[nb] == node) { // nb is child
                if (hasApple[nb] || needed[nb]) {
                    needed[node] = true;
                    time += 2;
                }
            }
        }
    }

    return time;
}

