public String sortString(String s) {
    int n = s.length();
    if (n == 0) return "";
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }
    StringBuilder sb = new StringBuilder(n);
    while (sb.length() < n) {
        // Ascending part
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                sb.append((char) (i + 'a'));
                freq[i]--;
                for (int j = i + 1; j < 26; j++) {
                    if (freq[j] > 0) {
                        sb.append((char) (j + 'a'));
                        freq[j]--;
                    }
                }
                break;
            }
        }
        // Descending part
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                sb.append((char) (i + 'a'));
                freq[i]--;
                for (int j = i - 1; j >= 0; j--) {
                    if (freq[j] > 0) {
                        sb.append((char) (j + 'a'));
                        freq[j]--;
                    }
                }
                break;
            }
        }
    }
    return sb.toString();
}

