public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    // Convert to a list of characters and sort it
    ArrayList<Character> list = new ArrayList<>();
    for (char c : s.toCharArray()) {
        list.add(c);
    }
    Collections.sort(list);

    StringBuilder result = new StringBuilder();

    while (!list.isEmpty()) {
        // Ascending phase
        char last = list.get(0);
        result.append(last);
        list.remove(0);

        while (true) {
            int idx = -1;
            for (int i = 0; i < list.size(); i++) {
                if (list.get(i) > last) {
                    idx = i;
                    break;
                }
            }
            if (idx == -1) {
                break;
            }
            last = list.get(idx);
            result.append(last);
            list.remove(idx);
        }

        if (list.isEmpty()) {
            break;
        }

        // Descending phase
        last = list.get(list.size() - 1);
        result.append(last);
        list.remove(list.size() - 1);

        while (true) {
            int idx = -1;
            for (int i = list.size() - 1; i >= 0; i--) {
                if (list.get(i) < last) {
                    idx = i;
                    break;
                }
            }
            if (idx == -1) {
                break;
            }
            last = list.get(idx);
            result.append(last);
            list.remove(idx);
        }
    }

    return result.toString();
}

