public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 0) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    int mid = n / 2;
    int len1 = mid;
    int len2 = n - mid;
    java.util.HashMap<Integer, java.util.HashSet<Integer>> map1 = new java.util.HashMap<>();
    java.util.HashMap<Integer, java.util.HashSet<Integer>> map2 = new java.util.HashMap<>();
    // Enumerate subsets for first half
    for (int mask = 0; mask < (1 << len1); mask++) {
        int sum = 0;
        int size = 0;
        for (int i = 0; i < len1; i++) {
            if ((mask >> i) & 1) {
                sum += nums[i];
                size++;
            }
        }
        java.util.HashSet<Integer> set = map1.computeIfAbsent(size, k -> new java.util.HashSet<>());
        set.add(sum);
    }
    // Enumerate subsets for second half
    for (int mask = 0; mask < (1 << len2); mask++) {
        int sum = 0;
        int size = 0;
        for (int i = 0; i < len2; i++) {
            if ((mask >> i) & 1) {
                sum += nums[mid + i];
                size++;
            }
        }
        java.util.HashSet<Integer> set = map2.computeIfAbsent(size, k -> new java.util.HashSet<>());
        set.add(sum);
    }
    // Check possible split sizes
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        for (int size1 = 0; size1 <= k; size1++) {
            int size2 = k - size1;
            java.util.HashSet<Integer> set1 = map1.get(size1);
            java.util.HashSet<Integer> set2 = map2.get(size2);
            if (set1 == null || set2 == null) continue;
            for (int s1 : set1) {
                if (set2.contains(target - s1)) return true;
            }
        }
    }
    return false;
}

