        java.util.HashSet<Integer>[] rightSets = new java.util.HashSet[rightLen + 1];
        for (int i = 0; i <= rightLen; i++) rightSets[i] = new java.util.HashSet<>();
        int rightMaskLimit = 1 << rightLen;
        for (int mask = 0; mask < rightMaskLimit; mask++) {
