            int sz = 0;
            for (int i = 0; i < rightLen; i++) {
                if ((mask >> i & 1) == 1) {
                    sum += right[i];
                    sz++;
                }
            }
            rightSets[sz].add(sum);
        }

        // Check combinations of left and right subsets
        for (int szL = 0; szL <= k; szL++) {
            int szR = k - szL;
            if (szL > left.length || szR > rightLen) continue;
