                sum += right[i];
                cnt++;
            }
        }
        rightSums[cnt].add(sum);
    }

    for (int leftCnt = 0; leftCnt <= leftLen; leftCnt++) {
        for (int leftSum : leftSums[leftCnt]) {
            for (int rightCnt = 0; rightCnt <= rightLen; rightCnt++) {
                int totalSize = leftCnt + rightCnt;
                if (totalSize == 0 || totalSize == n) continue;
                long targetNum = (long) totalSum * totalSize;
                if (targetNum % n != 0) continue;
                int targetSum = (int) (targetNum / n);
                int neededRightSum = targetSum - leftSum;
                if (rightSums[rightCnt].contains(neededRightSum)) return true;
            }
        }
    }
    return false;
}

