private boolean can(int[] nums, int start, int k, int sum, java.util.HashMap<String, Boolean> memo) {
    if (k == 0) {
        return sum == 0;
    }
    if (sum < 0) {
        return false;
    }
    String key = start + "#" + k + "#" + sum;
    Boolean cached = memo.get(key);
    if (cached != null) {
        return cached;
    }
    for (int i = start; i < nums.length; i++) {
        if (can(nums, i + 1, k - 1, sum - nums[i], memo)) {
            memo.put(key, Boolean.TRUE);
            return true;
        }
    }
    memo.put(key, Boolean.FALSE);
    return false;
}

