        for (int size = n - 1; size >= 0; size--) {
            java.util.HashSet<Integer> prev = sums[size];
            java.util.HashSet<Integer> next = sums[size + 1];
            for (int value : prev) {
                next.add(value + num);
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n == 0) {
            int target = (totalSum * k) / n;
            if (sums[k].contains(target)) {
                return true;
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return 0;
    int prev2 = 0; // cost for step -1 (starting before first step)
    int prev1 = 0; // cost for step 0 (starting before second step)
    for (int i = 2; i <= n; i++) {
        int costForPrevStep = prev1 + cost[i - 1];
        int costForPrevPrevStep = prev2 + cost[i - 2];
        int curr = Math.min(costForPrevStep, costForPrevPrevStep);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n <= 2) {
        return 0;
    }
    int first = cost[0];
    int second = cost[1];
    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(first, second);
        first = second;
        second = current;
    }
    return Math.min(first, second);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int dp0 = cost[0];
    int dp1 = cost[1];
    for (int i = 2; i < n; i++) {
        int curr = cost[i] + Math.min(dp0, dp1);
        dp0 = dp1;
        dp1 = curr;
    }
    return Math.min(dp0, dp1);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int prev2 = 0; // cost to reach step i-2
    int prev1 = 0; // cost to reach step i-1
    for (int i = 2; i <= n; i++) {
        int curr = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int fromPrev = dp[i - 1] + cost[i - 1];
        int fromPrevPrev = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(fromPrev, fromPrevPrev);
    }
    return dp[n];
}

