public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k == 0) return true;          // an empty string trivially qualifies
    if (n < k) return false;          // not enough length to contain all codes

    int total = 1 << k;               // total number of binary strings of length k
    boolean[] seen = new boolean[total];
    int code = 0;
    int mask = total - 1;
    int count = 0;

    // Build the initial code for the first k-1 characters
    for (int i = 0; i < k - 1; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }

    // Slide over the string, updating code and marking seen values
    for (int i = k - 1; i < n; i++) {
        code = ((code << 1) | (s.charAt(i) - '0')) & mask;
        if (!seen[code]) {
            seen[code] = true;
            count++;
            if (count == total) return true; // all codes found
        }
    }

    return false; // some codes missing
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) return false;
    int n = s.length();
    if (n < k) return false;
    int totalCodes = 1 << k; // number of binary strings of length k
    boolean[] seen = new boolean[totalCodes];
    int mask = totalCodes - 1;
    int curr = 0;
    int count = 0;
    for (int i = 0; i < n; i++) {
        curr = ((curr << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[curr]) {
                seen[curr] = true;
                count++;
                if (count == totalCodes) return true;
            }
        }
    }
    return count == totalCodes;
}

