    if (total > Integer.MAX_VALUE / 2) {
        // too large for array, fall back to set
        java.util.HashSet<Integer> set = new java.util.HashSet<>(total);
        int mask = total - 1;
        int val = 0;
        for (int i = 0; i < n; i++) {
            val = ((val << 1) & mask) | (s.charAt(i) - '0');
            if (i >= k - 1) {
                set.add(val);
            }
        }
        return set.size() == total;
    }
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int val = 0;
    int count = 0;
    for (int i = 0; i < n; i++) {
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[val]) {
                seen[val] = true;
                count++;
            }
        }
    }
    return count == total;
}

public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true; // only empty string case
    int n = s.length();
    if (k > n) return false;
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int count = 0;

    // Build the first k-length value
    int current = 0;
    for (int i = 0; i < k; i++) {
        current = (current << 1) | (s.charAt(i) - '0');
    }
    if (!seen[current]) {
        seen[current] = true;
        count++;
    }

    // Slide through the string
    for (int i = k; i < n; i++) {
        current = ((current << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[current]) {
            seen[current] = true;
            count++;
        }
        if (count == total) return true;
    }

    return count == total;
}

