public int minInsertions(String s) {
    int balance = 0;      // number of unmatched '(' so far
    int insertions = 0;   // number of inserted brackets

    for (char c : s.toCharArray()) {
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance > 0) {
                balance--;          // match an existing '('
            } else {
                insertions++;        // need to insert a '(' before this ')'
            }
        }
    }

    // Remaining unmatched '(' need closing ')'
    return insertions + balance;
}

