public int minOperations(int n) {
    int k = (n - 1) / 2;          // Last index with value <= target
    int m = n - (k + 1);          // Count of indices with value > target
    return m * (k + 1);           // Total excess equals operations needed
}

public int minOperations(int n) {
    int start = (n + 1) / 2;
    long operations = (long) start * (n - start);
    return (int) operations;
}

