    // Generate Fibonacci numbers up to k
    int[] fib = new int[50]; // sufficient size for all possible k values
    int len = 0;
    int a = 1;
    int b = 1;
    while (a <= k) {
        fib[len++] = a;
        int next = a + b;
        a = b;
        b = next;
    }

    // Greedy subtraction from the largest Fibonacci number downwards
    int count = 0;
    int remaining = k;
    for (int i = len - 1; i >= 0 && remaining > 0; i--) {
        if (fib[i] <= remaining) {
            remaining -= fib[i];
            count++;
        }
    }
    return count;
}

