public int kthFactor(int n, int k) {
    List<Integer> small = new ArrayList<>();
    List<Integer> large = new ArrayList<>();
    int limit = (int)Math.sqrt(n);
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            small.add(i);
            int counterpart = n / i;
            if (counterpart != i) {
                large.add(counterpart);
            }
        }
    }
    // large factors are in descending order; reverse to ascending
    Collections.reverse(large);
    // Combine small and large
    for (int factor : large) {
        small.add(factor);
    }
    if (k <= 0 || k > small.size()) {
        return -1;
    }
    return small.get(k - 1);
}

public int kthFactor(int n, int k) {
    // List to store divisors less than or equal to sqrt(n)
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    // List to store paired divisors greater than sqrt(n)
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();

    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int paired = n / i;
            if (paired != i) {
                large.add(paired);
            }
        }
    }

    // The 'large' list currently holds divisors in descending order.
    // Reverse it to get ascending order.
    java.util.Collections.reverse(large);

    // Concatenate the two lists to get all divisors in ascending order
    java.util.List<Integer> all = new java.util.ArrayList<>(small.size() + large.size());
    all.addAll(small);
    all.addAll(large);

    if (k <= 0 || k > all.size()) {
        return -1;
    }
    return all.get(k - 1);
}

public int kthFactor(int n, int k) {
    List<Integer> lower = new ArrayList<>();
    List<Integer> higher = new ArrayList<>();
    for (int i = 1; (long)i * i <= n; i++) {
        if (n % i == 0) {
            lower.add(i);
            int div = n / i;
            if (div != i) {
                higher.add(div);
            }
        }
    }
    // Append the higher divisors in reverse order to maintain ascending order
    for (int i = higher.size() - 1; i >= 0; i--) {
        lower.add(higher.get(i));
    }
    if (k > lower.size()) {
        return -1;
    }
    return lower.get(k - 1);
}

