public String makeGood(String s) {
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char last = stack.charAt(len - 1);
            if (Math.abs(last - c) == 32) { // 'A' to 'Z' difference is 32
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public String makeGood(String s) {
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char current = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            if (Character.toLowerCase(top) == Character.toLowerCase(current) &&
                Character.isLowerCase(top) != Character.isLowerCase(current)) {
                stack.deleteCharAt(len - 1); // remove the pair
                continue;
            }
        }
        stack.append(current);
    }
    return stack.toString();
}

public String makeGood(String s) {
