    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (sb.length() > 0) {
            char last = sb.charAt(sb.length() - 1);
            // Check if c and last are same letter in opposite cases
            if (Math.abs(c - last) == 32) {
                sb.setLength(sb.length() - 1); // remove the pair
                continue;
            }
        }
        sb.append(c);
    }
    return sb.toString();
}

public String makeGood(String s) {
    char[] stack = new char[s.length()];
    int top = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (top > 0 && Math.abs(c - stack[top - 1]) == 32) {
            top--; // Remove the bad pair
        } else {
            stack[top++] = c;
        }
    }
    return new String(stack, 0, top);
}

public String makeGood(String s) {
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (stack.length() > 0 && Math.abs(stack.charAt(stack.length() - 1) - c) == 32) {
            stack.setLength(stack.length() - 1);
        } else {
            stack.append(c);
        }
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    return dfs(0, new java.util.HashSet<>(), s);
}

private int dfs(int index, java.util.Set<String> used, String s) {
    if (index == s.length()) {
        return 0;
    }
    int best = 0;
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!used.contains(sub)) {
            used.add(sub);
            int curr = 1 + dfs(end, used, s);
            if (curr > best) {
                best = curr;
            }
            used.remove(sub);
        }
    }
    return best;
}

public int maxUniqueSplit(String s) {
    return dfs(s, 0, new java.util.HashSet<String>());
}

private int dfs(String s, int index, java.util.Set<String> used) {
    if (index == s.length()) {
        return 0;
    }
    int max = 0;
    for (int i = index + 1; i <= s.length(); i++) {
        String sub = s.substring(index, i);
        if (!used.contains(sub)) {
            used.add(sub);
            max = Math.max(max, 1 + dfs(s, i, used));
            used.remove(sub);
        }
    }
    return max;
}

public int maxUniqueSplit(String s) {
    int max = 0;
    int n = s.length();
    java.util.Deque<java.util.Map.Entry<Integer, java.util.Set<String>>> stack = new java.util.ArrayDeque<>();
    stack.push(new java.util.AbstractMap.SimpleEntry<>(0, new java.util.HashSet<>()));
    while (!stack.isEmpty()) {
        java.util.Map.Entry<Integer, java.util.Set<String>> current = stack.pop();
        int pos = current.getKey();
        java.util.Set<String> used = current.getValue();
        if (pos == n) {
            if (used.size() > max) {
                max = used.size();
            }
            continue;
        }
        for (int i = pos + 1; i <= n; i++) {
            String sub = s.substring(pos, i);
            if (!used.contains(sub)) {
                java.util.Set<String> newUsed = new java.util.HashSet<>(used);
                newUsed.add(sub);
                stack.push(new java.util.AbstractMap.SimpleEntry<>(i, newUsed));
            }
        }
    }
    return max;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int[] max = new int[1];
    dfs(s, 0, new java.util.HashSet<>(), 0, max);
    return max[0];
}

private void dfs(String s, int index, java.util.Set<String> used, int count, int[] max) {
    if (index == s.length()) {
        if (count > max[0]) {
            max[0] = count;
        }
        return;
    }
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(s, end, used, count + 1, max);
            used.remove(sub);
        }
    }
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    int maxCount = 1; // at least one substring (the whole string)
    int totalMasks = 1 << (n - 1); // splits between characters

    for (int mask = 0; mask < totalMasks; mask++) {
        java.util.HashSet<String> seen = new java.util.HashSet<>();
        int start = 0;
        boolean duplicate = false;

        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) { // split after character i
                String part = s.substring(start, i + 1);
                if (!seen.add(part)) { // already seen
                    duplicate = true;
                    break;
                }
                start = i + 1;
            }
        }

        if (duplicate) continue;

        // last part
        String part = s.substring(start, n);
        if (!seen.add(part)) continue; // duplicate at the end

        int count = seen.size(); // number of unique substrings
        if (count > maxCount) {
            maxCount = count;
        }
    }

    return maxCount;
}

