public static int singleNumber(int[] nums) {
    int ones = 0;
    int twos = 0;
    for (int num : nums) {
        // Update twos with bits that appear twice
        twos |= ones & num;
        // Update ones with bits that appear once
        ones ^= num;
        // Mask for bits that have appeared three times
        int commonMask = ones & twos;
        // Remove bits that have appeared three times from ones and twos
        ones &= ~commonMask;
        twos &= ~commonMask;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int bitSum = 0;
        for (int n : nums) {
            bitSum += (n >> i) & 1;
        }
        result |= (bitSum % 3) << i;
    }
    return result;
}

public static int singleNumber(int[] nums) {
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int bitCount = 0;
        int mask = 1 << i;
        for (int num : nums) {
            if ((num & mask) != 0) {
                bitCount++;
            }
        }
        if ((bitCount % 3) != 0) {
            result |= mask;
        }
    }
    return result;
}

public static int singleNumber(int[] nums) {
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int bitSum = 0;
        for (int num : nums) {
            if (((num >> i) & 1) == 1) {
                bitSum++;
            }
        }
        if (bitSum % 3 != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static int singleNumber(int[] nums) {
    int ones = 0, twos = 0, mask;
    for (int num : nums) {
        twos |= ones & num;
        ones ^= num;
        mask = ~(ones & twos);
        ones &= mask;
        twos &= mask;
    }
    return ones;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low <= 0 && high >= 0) {
        result.add(0);
    }

    if (high < 1) {
        Collections.sort(result);
        return result;
    }

    Queue<Long> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }

    while (!queue.isEmpty()) {
        long current = queue.poll();
        if (current > high) {
            continue;
        }
        if (current >= low) {
            result.add((int) current);
        }

        int lastDigit = (int) (current % 10);

        if (lastDigit > 0) {
            long next = current * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = current * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }

    Collections.sort(result);
    return result;
}

