public static int countDigitOne(int n) {
    if (n <= 0) return 0;
    long count = 0;
    for (long p = 1; p <= n; p *= 10) {
        long high = n / (p * 10);
        int cur = (int) ((n / p) % 10);
        long low = n % p;
        if (cur == 0) {
            count += high * p;
        } else if (cur == 1) {
            count += high * p + low + 1;
        } else {
            count += (high + 1) * p;
        }
    }
    return (int) count;
}

public static int countDigitOne(int n) {
    int count = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long lower   = n % factor;
        long current = (n / factor) % 10;
        long higher  = n / (factor * 10);
        if (current == 0) {
            count += (int) (higher * factor);
        } else if (current == 1) {
            count += (int) (higher * factor + lower + 1);
        } else {
            count += (int) ((higher + 1) * factor);
        }
    }
    return count;
}

