public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n - (n / factor) * factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);

        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + (lower + 1);
        } else {
            count += (higher + 1) * factor;
        }

        // prevent overflow for the next factor
        if (factor > Long.MAX_VALUE / 10) {
            break;
        }
        factor *= 10;
    }
    return (int) count;
}

