public static String addThousandSeparator(int n) {
    // Handle zero explicitly
    if (n == 0) {
        return "0";
    }

    boolean negative = n < 0;
    int absValue = Math.abs(n);
    String numberStr = String.valueOf(absValue);
    StringBuilder sb = new StringBuilder();

    int digitCount = 0;
    // Build the formatted string in reverse order
    for (int i = numberStr.length() - 1; i >= 0; i--) {
        sb.append(numberStr.charAt(i));
        digitCount++;
        if (digitCount == 3 && i != 0) {
            sb.append('.'); // Insert dot after every three digits
            digitCount = 0;
        }
    }

    // If the input was negative, add the minus sign
    if (negative) {
        sb.append('-');
    }

    // Reverse to get the final result
    return sb.reverse().toString();
}

