        if (v > maxVal) maxVal = v;
    }
    int[] unique = new int[freqMap.size()];
    int[] freq = new int[freqMap.size()];
    int idx = 0;
    for (java.util.Map.Entry<Integer, Integer> e : freqMap.entrySet()) {
        unique[idx] = e.getKey();
        freq[idx] = e.getValue();
        idx++;
    }
    int size = unique.length;
    int[][] good = new int[size][size];
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            int sum = unique[i] + unique[j];
            int r = (int) Math.round(Math.sqrt(sum));
            good[i][j] = (r * r == sum) ? 1 : 0;
        }
    }
    java.util.Map<Long, Integer> cache = new java.util.HashMap<>();
    return dfs(-1, n, unique, freq, good, cache);
}

private static int dfs(int prevIdx, int remaining, int[] uniq, int[] freq, int[][] good, java.util.Map<Long, Integer> cache) {
    if (remaining == 0) return 1;
    long key = ((long) prevIdx + 1) << 32 | (long) remaining;
    Integer cached = cache.get(key);
    if (cached != null) return cached;
    int ans = 0;
    for (int i = 0; i < uniq.length; i++) {
        if (freq[i] == 0) continue;
        if (prevIdx != -1 && good[prevIdx][i] == 0) continue;
        freq[i]--;
        ans += dfs(i, remaining - 1, uniq, freq, good, cache);
        freq[i]++;
    }
    cache.put(key, ans);
    return ans;
}

