private static List<String> build(int curr, int target) {
    List<String> result = new ArrayList<>();
    if (curr == 0) {
        result.add("");
        return result;
    }
    if (curr == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }

    List<String> inner = build(curr - 2, target);
    for (String mid : inner) {
        if (curr != target) {
            result.add("0" + mid + "0");
        }
        result.add("1" + mid + "1");
        result.add("8" + mid + "8");
