        result.add("9" + mid + "6");
    }
    return result;
}

private static void build(int left, int right, char[] buffer, java.util.List<String> result) {
    if (left > right) {
        result.add(new java.lang.String(buffer));
        return;
    }
    if (left == right) {
        char[] mids = {'0', '1', '8'};
        for (char m : mids) {
            buffer[left] = m;
            result.add(new java.lang.String(buffer));
        }
        return;
    }
    char[] digits = {'0', '1', '6', '8', '9'};
    for (char d : digits) {
        if (left == 0 && buffer.length > 1 && d == '0') continue; // avoid leading zero
        buffer[left] = d;
        buffer[right] = mirror(d);
        build(left + 1, right - 1, buffer, result);
    }
}

private static char mirror(char d) {
    switch (d) {
        case '0': return '0';
        case '1': return '1';
        case '6': return '9';
        case '8': return '8';
        case '9': return '6';
        default:  return ' '; // should not happen
    }
}

