                cur /= 10;
            }
            cur++;
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>();
    if (n <= 0) {
        return res;
    }
    int curr = 1;
    for (int i = 0; i < n; i++) {
        res.add(curr);
        if (curr * 10 <= n) {
            curr *= 10;
        } else if (curr % 10 != 9 && curr + 1 <= n) {
            curr++;
        } else {
            while (curr % 10 == 9 || curr + 1 > n) {
                curr /= 10;
            }
            curr++;
        }
    }
    return res;
}

