    for (int i = 0; i <= s.length(); i++) {
        char c = (i == s.length() ? ' ' : s.charAt(i));
        if (c == ' ') {
            for (int j = i - 1; j >= start; j--) {
                result.append(s.charAt(j));
            }
            if (i < s.length()) {
                result.append(' ');
            }
            start = i + 1;
        }
    }
    return result.toString();
}

